===./package.json===
{
  "name": "stallion",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "workspaces": [
    "packages/*",
    "apps/*"
  ],
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "dev": "npm run dev -w @stallion/web",
    "fix": "biome check --write . && cargo fmt --all",
    "lint": "biome check .",
    "lint:rust": "cargo fmt --all --check && cargo clippy --workspace --all-targets -- -D warnings",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "vitest run",
    "test:rust": "cargo test --workspace",
    "build": "npm run build --workspaces --if-present",
    "build:worker": "cd crates/server && worker-build --release",
    "deploy:dry": "wrangler deploy --dry-run --outdir ~/development/.tmp/stallion-dry"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.5.14",
    "typescript": "^7.0.2",
    "vitest": "^5.0.2",
    "wrangler": "^4.141.0"
  }
}
